"""Route path matching and dictionary consolidation."""
from typing import Dict, Any, List

def deep_merge_matchers(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    res = dict(base)
    for k, v in override.items():
        if k in res and isinstance(res[k], dict) and isinstance(v, dict):
            res[k] = deep_merge_matchers(res[k], v)
        else:
            res[k] = v
    return res

def normalize_prefix(path: str) -> str:
    return "/" + path.strip("/")

def merge_header_matchers(base_matchers: List[str], override_matchers: List[str]) -> List[str]:
    """Merge header matchers with override taking precedence.

    This ensures that environment overrides properly extend base configurations
    instead of replacing them, which was causing the truncation issue in INC-9206.
    """
    if not override_matchers:
        return base_matchers
    if not base_matchers:
        return override_matchers

    # Create a set of base matchers for quick lookup
    base_set = set(base_matchers)
    # Build result with override matchers taking precedence
    result = []
    seen = set()

    # Add override matchers first (they take precedence)
    for matcher in override_matchers:
        if matcher not in seen:
            result.append(matcher)
            seen.add(matcher)

    # Add base matchers that aren't overridden
    for matcher in base_matchers:
        if matcher not in seen:
            result.append(matcher)
            seen.add(matcher)

    return result
