"""Service mesh routing configuration compiler."""
from typing import Dict, Any
from matcher_utils import deep_merge_matchers, normalize_prefix, merge_header_matchers

def compile_route_profile(mesh_id: str, base_rules: Dict[str, Any], env_rules: Dict[str, Any]) -> Dict[str, Any]:
    merged = deep_merge_matchers(base_rules, env_rules)
    prefix = normalize_prefix(merged.get("prefix", "/"))
    primary = extract_primary_route(prefix)

    # Handle header matchers merging
    base_matchers = base_rules.get("headers", {}).get("match", [])
    override_matchers = env_rules.get("headers", {}).get("match", [])
    merged_matchers = merge_header_matchers(base_matchers, override_matchers)

    # Update merged rules with the proper header matchers
    merged["headers"] = merged.get("headers", {})
    merged["headers"]["match"] = merged_matchers

    return {
        "mesh_id": mesh_id,
        "prefix": prefix,
        "primary": primary,
        "segments": count_route_segments(prefix),
        "rules": merged
    }
